//! The results of the date and time checkers, as TS `@markuplint/types` reports them.
//!
//! The cases are the inputs of `check-datetime/*.spec.ts` and `check-datetime-subtypes.spec.ts`,
//! plus inputs the rule specs check and edge cases; every expectation is the result of TS `check()`
//! (or of the TS checker function) for that input, run with `TZ=UTC` (see `get_max_week_num`).
//! Offsets are byte offsets; columns are UTF-16 code units as in TS.

use markuplint_types::check::check;
use markuplint_types::check::types::{CheckResult, Reason, Type};
use markuplint_types::whatwg::datetime::{
    check_date_string, check_date_string_with_optional_time, check_datetime, check_duration_component_list_string,
    check_duration_iso8601_like_string, check_global_date_and_time_string, check_local_date_and_time_string,
    check_month_string, check_normalized_local_date_and_time_string, check_time_string, check_time_zone_offset_string,
    check_week_string, check_year_string, check_yearless_date_string, get_max_week_num,
};

#[derive(Clone, Copy)]
enum Kind {
    /// The TS checker function of that name.
    Fn,
    /// TS `check(value, keyword)`.
    Kw,
}
use Kind::{Fn, Kw};

/// The expected unmatched result.
struct E {
    reason: Reason,
    raw: &'static str,
    offset: usize,
    line: usize,
    column: usize,
    part_name: Option<&'static str>,
    /// `None`: TS has no `expects`.
    expects: Option<&'static [(&'static str, &'static str)]>,
    ref_: Option<&'static str>,
    pass_count: Option<usize>,
}

fn run(kind: Kind, name: &str, value: &str) -> CheckResult {
    match kind {
        Kw => check(value, &Type::Keyword(name.into()), None),
        Fn => {
            let f: fn(&str) -> CheckResult = match name {
                "checkDateString" => check_date_string,
                "checkDateStringWithOptionalTime" => check_date_string_with_optional_time,
                "checkDateTime" => check_datetime,
                "checkDurationComponentListString" => check_duration_component_list_string,
                "checkDurationISO8601LikeString" => check_duration_iso8601_like_string,
                "checkGlobalDateAndTimeString" => check_global_date_and_time_string,
                "checkLocalDateAndTimeString" => check_local_date_and_time_string,
                "checkMonthString" => check_month_string,
                "checkNormalizedLocalDateAndTimeString" => check_normalized_local_date_and_time_string,
                "checkTimeString" => check_time_string,
                "checkTimeZoneOffsetString" => check_time_zone_offset_string,
                "checkWeekString" => check_week_string,
                "checkYearString" => check_year_string,
                "checkYearlessDateString" => check_yearless_date_string,
                _ => panic!("unknown checker {name}"),
            };
            f(value)
        }
    }
}

fn same_reason(a: &Reason, b: &Reason) -> bool {
    // A `NaN` bound (the week of a year past the JS date range) equals `NaN`.
    let eq = |x: Option<f64>, y: Option<f64>| match (x, y) {
        (Some(x), Some(y)) => x == y || (x.is_nan() && y.is_nan()),
        (x, y) => x.is_none() && y.is_none(),
    };
    match (a, b) {
        (
            Reason::OutOfRangeWithBounds { gt, gte, lt, lte },
            Reason::OutOfRangeWithBounds {
                gt: gt2,
                gte: gte2,
                lt: lt2,
                lte: lte2,
            },
        ) => eq(*gt, *gt2) && eq(*gte, *gte2) && eq(*lt, *lt2) && eq(*lte, *lte2),
        _ => a == b,
    }
}

#[test]
fn max_week() {
    assert!((get_max_week_num(1976.0) - 53.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(1977.0) - 52.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(1978.0) - 52.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(1979.0) - 52.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(1981.0) - 53.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(2021.0) - 52.0).abs() < f64::EPSILON);
    assert!((get_max_week_num(2026.0) - 53.0).abs() < f64::EPSILON);
    // `Date.UTC` maps 0–99 to 1900–1999: 1903 has 53 weeks.
    assert!((get_max_week_num(3.0) - 53.0).abs() < f64::EPSILON);
    assert!(get_max_week_num(275_760.0).is_nan());
}

#[test]
fn ts_results() {
    let mut failures = Vec::new();
    for (kind, name, value, expected) in CASES {
        let res = run(*kind, name, value);
        let ok = match (expected, &res) {
            (None, CheckResult::Matched) => true,
            (Some(e), CheckResult::Unmatched(u)) => {
                let expects_ok = match (kind, e.expects) {
                    // TS keeps a checker's `expects: []`; Rust has no empty-but-present
                    // `expects`, so `check_keyword_type` fills it from the definition.
                    (Kw, Some([])) => true,
                    (_, None) => u.expects.is_empty(),
                    (_, Some(list)) => {
                        u.expects.len() == list.len()
                            && u.expects
                                .iter()
                                .zip(list.iter())
                                .all(|(a, (t, v))| format!("{:?}", a.type_).to_lowercase() == *t && a.value == *v)
                    }
                };
                same_reason(&u.reason, &e.reason)
                    && u.raw == e.raw
                    && u.offset == e.offset
                    && u.line == e.line
                    && u.column == e.column
                    && u.part_name.as_deref() == e.part_name
                    && u.ref_.as_deref() == e.ref_
                    && u.pass_count == e.pass_count
                    && expects_ok
            }
            _ => false,
        };
        if !ok {
            failures.push(format!("{name}({value:?}): {res:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

